-- CD controller engine: a small accumulator machine that runs the CD controller's decisions (firmware in
-- rtl/cd_fw_pkg.vhd, generated by tools/cdasm.py from rtl/cd_fw/cd_fw.py; design: docs/cd_engine.md).
--
-- One instruction per clock (a taken branch included: the next address is computed in the same clock and the
-- program ROM is read with it). Instruction word, 40 bits:
--    39..34 op | 33..27 r | 26..0 imm (immediates, zero extended)
--    jumps: target in the low FW_AW bits, 16..12 bit (JBS / JBC), 19..12 8-bit value (JEQ / JNE)
--    1..0 byte (LDB, MOVB); 26..20 destination (MOV, MOVB: r is the source); SETB / CLRB: the mask
-- Operand r: 0..63 register file (MLAB, asynchronous read), 64..95 I/O port r - 64 (io_rdata, combinational from
-- the parent, io_raddr = r - 64). Stores (ST, STI, MOV, MOVB; SETB, CLRB, ORS on registers only) write the result
-- to register r, or to I/O port r - 64 (io_we for one clock).
-- start (one clock, engine idle) runs the code at ENTRY; WAIT ends it (busy low again). reset: idle.
--
-- Op codes (keep in sync with tools/cdasm.py):
--    00ifff  ALU, i: source is the immediate (else operand r), fff: 0 LD, 1 AND, 2 OR, 3 XOR, 4 ADD, 5 SUB,
--            6 MUL (A(26..0) * source(26..0), low 32 bits; also the left shifts), 7 CMP (SUB without writing A)
--    01mmmm  0 SHR1, 1 SHR8, 2 LDB (A = byte of r), 3 ST (r = A), 4 SETB (r |= imm), 5 CLRB (r &= imm), 6 WAIT,
--            7 STI (r = imm), 8 MOV (dest = r), 9 MOVB (dest = byte of r), 10 ORS (r = r or A);
--            none of them changes A or the flags except SHR1, SHR8, LDB
--    10cccn  jumps: ccc 0 always (J; n = 1: NOP), 1 Z, 2 C, 3 operand bit, 4 operand = 8-bit value;
--            n inverts the condition
-- Flags: Z from every result written to A and from CMP, C (borrow for SUB / CMP) from ADD, SUB, CMP.
library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

library mem;
use work.cd_fw_pkg.all;

entity cd_engine is
   port
   (
      clk       : in  std_logic;
      reset     : in  std_logic;
      start     : in  std_logic;
      busy      : out std_logic;

      io_raddr  : out unsigned(4 downto 0);
      io_rdata  : in  std_logic_vector(31 downto 0);
      io_waddr  : out unsigned(4 downto 0);
      io_wdata  : out std_logic_vector(31 downto 0);
      io_we     : out std_logic
   );
end entity;

architecture arch of cd_engine is

   -- program ROM (M10K): the constant FW of rtl/cd_fw_pkg.vhd, read with the next instruction address
   signal rom      : tfw := FW;
   signal running  : std_logic := '0';
   signal pc       : unsigned(FW_AW - 1 downto 0) := (others => '0');
   signal pc_next  : unsigned(FW_AW - 1 downto 0);
   signal instr    : std_logic_vector(39 downto 0) := (others => '0');

   signal A        : unsigned(31 downto 0) := (others => '0');
   signal flagZ    : std_logic := '0';
   signal flagC    : std_logic := '0';

   signal op       : std_logic_vector(5 downto 0);
   signal r        : unsigned(6 downto 0);
   signal target   : unsigned(FW_AW - 1 downto 0);
   signal wa       : unsigned(6 downto 0);   -- store address: r, or the destination of MOV / MOVB
   signal bitidx   : integer range 0 to 31;

   -- decoded
   signal isALU    : std_logic;
   signal isMisc   : std_logic;
   signal isJump   : std_logic;
   signal fn       : std_logic_vector(2 downto 0);
   signal mop      : std_logic_vector(3 downto 0);
   signal useImm   : std_logic;
   signal isLDB    : std_logic;
   signal isSETB   : std_logic;
   signal isCLRB   : std_logic;
   signal isSTI    : std_logic;
   signal isMOV    : std_logic;   -- MOV, MOVB
   signal isByte   : std_logic;   -- LDB, MOVB: the source is a byte of the operand
   signal isStore  : std_logic;

   signal rf_q     : std_logic_vector(31 downto 0);
   signal rf_we    : std_logic;
   signal opnd     : unsigned(31 downto 0);
   signal src      : unsigned(31 downto 0);

   signal logic    : unsigned(31 downto 0);
   signal lmode    : std_logic_vector(2 downto 0);
   signal rsel     : std_logic_vector(1 downto 0);
   signal subtract : std_logic;
   signal srcx     : unsigned(31 downto 0);
   signal sumx     : unsigned(33 downto 0);
   signal sum      : unsigned(32 downto 0);
   signal prod     : unsigned(53 downto 0);
   signal shr      : unsigned(31 downto 0);
   signal result   : unsigned(31 downto 0);
   signal writeA   : std_logic;
   signal setC     : std_logic;
   signal resZ     : std_logic;
   signal cond     : std_logic;
   signal taken    : std_logic;

begin

   busy <= running;

   op     <= instr(39 downto 34);
   r      <= unsigned(instr(33 downto 27));
   target <= unsigned(instr(FW_AW - 1 downto 0));
   bitidx <= to_integer(unsigned(instr(16 downto 12)));

   isALU  <= '1' when op(5 downto 4) = "00" else '0';
   isMisc <= '1' when op(5 downto 4) = "01" else '0';
   isJump <= op(5);
   fn     <= op(2 downto 0);
   mop    <= op(3 downto 0);
   isLDB  <= '1' when isMisc = '1' and mop = "0010" else '0';
   isSETB <= '1' when isMisc = '1' and mop = "0100" else '0';
   isCLRB <= '1' when isMisc = '1' and mop = "0101" else '0';
   isSTI  <= '1' when isMisc = '1' and mop = "0111" else '0';
   isMOV  <= '1' when isMisc = '1' and (mop = "1000" or mop = "1001") else '0';
   isByte <= '1' when isMisc = '1' and (mop = "0010" or mop = "1001") else '0';
   isStore <= '1' when isMisc = '1' and (mop = "0011" or mop = "0100" or mop = "0101" or mop = "0111" or
                                         mop = "1000" or mop = "1001" or mop = "1010") else '0';
   useImm <= (op(3) and isALU) or isSETB or isCLRB or isSTI;
   wa     <= unsigned(instr(26 downto 20)) when isMOV = '1' else r;

   -- register file: MLAB, asynchronous read, written by the stores to 0..63
   irf : entity mem.RamMLAB
   generic map (width => 32, widthad => 6)
   port map
   (
      inclock   => clk,
      wren      => rf_we,
      data      => std_logic_vector(result),
      wraddress => std_logic_vector(wa(5 downto 0)),
      rdaddress => std_logic_vector(r(5 downto 0)),
      q         => rf_q
   );

   rf_we <= running and isStore and not wa(6);
   io_raddr <= r(4 downto 0);
   io_waddr <= wa(4 downto 0);
   io_wdata <= std_logic_vector(result);
   io_we    <= running and isStore and wa(6);

   -- operand, and the source: the operand, the immediate, or a byte of the operand (LDB, MOVB)
   opnd <= unsigned(rf_q) when r(6) = '0' else unsigned(io_rdata);
   process (all)
   begin
      if (useImm = '1') then
         src <= "00000" & unsigned(instr(26 downto 0));
      elsif (isByte = '1') then
         src <= (others => '0');
         case (instr(1 downto 0)) is
            when "00"   => src(7 downto 0) <= opnd(7 downto 0);
            when "01"   => src(7 downto 0) <= opnd(15 downto 8);
            when "10"   => src(7 downto 0) <= opnd(23 downto 16);
            when others => src(7 downto 0) <= opnd(31 downto 24);
         end case;
      else
         src <= opnd;
      end if;
   end process;

   -- logic unit: LD / AND / OR / XOR, LDB / STI / MOV / MOVB (source), ST (A), SETB, CLRB, ORS; result select
   process (all)
   begin
      lmode <= "0" & fn(1 downto 0);   -- 0 source, 1 A and, 2 A or, 3 A xor
      rsel  <= "00";                   -- 0 logic, 1 sum, 2 product, 3 right shift
      if (isMisc = '1') then
         case (mop) is
            when "0000" | "0001" => rsel <= "11";
            when "0011" => lmode <= "100";   -- A
            when "0100" => lmode <= "101";   -- operand or source
            when "0101" => lmode <= "110";   -- operand and source
            when "1010" => lmode <= "010";   -- A or the operand
            when others => lmode <= "000";
         end case;
      elsif (fn(2) = '1') then
         if (fn = "110") then rsel <= "10"; else rsel <= "01"; end if;
      end if;
   end process;

   process (all)
   begin
      case (lmode) is
         when "001"  => logic <= A and src;
         when "010"  => logic <= A or src;
         when "011"  => logic <= A xor src;
         when "100"  => logic <= A;
         when "101"  => logic <= opnd or src;
         when "110"  => logic <= opnd and src;
         when others => logic <= src;
      end case;
   end process;

   subtract <= fn(0);   -- 5 SUB, 7 CMP (4 ADD)
   srcx     <= not src when subtract = '1' else src;
   sumx     <= ('0' & A & '1') + ('0' & srcx & subtract);   -- carry in: subtract
   sum      <= sumx(33 downto 1);
   prod     <= A(26 downto 0) * src(26 downto 0);
   shr      <= x"00" & A(31 downto 8) when op(0) = '1' else '0' & A(31 downto 1);

   with rsel select result <=
      logic           when "00",
      sum(31 downto 0)  when "01",
      prod(31 downto 0) when "10",
      shr             when others;

   writeA <= '1' when (isALU = '1' and fn /= "111") or (isMisc = '1' and mop(3 downto 1) = "000") or isLDB = '1' else '0';
   setC   <= '1' when isALU = '1' and fn(2) = '1' and fn /= "110" else '0';
   resZ   <= '1' when result = 0 else '0';

   -- jumps
   process (all)
   begin
      case (op(3 downto 1)) is
         when "001"  => cond <= flagZ;
         when "010"  => cond <= flagC;
         when "011"  => cond <= opnd(bitidx);
         when "100"  => if (opnd(31 downto 8) = 0 and opnd(7 downto 0) = unsigned(instr(19 downto 12))) then cond <= '1'; else cond <= '0'; end if;
         when others => cond <= '1';
      end case;
   end process;
   taken <= isJump and (cond xor op(0));

   -- next instruction address (the ROM is read with it at the edge)
   process (all)
   begin
      pc_next <= pc + 1;
      if (running = '0' or (isMisc = '1' and mop = "0110")) then         -- idle, WAIT
         pc_next <= to_unsigned(FW_ENTRY, FW_AW);
      elsif (taken = '1') then
         pc_next <= target;
      end if;
   end process;

   process (clk)
   begin
      if rising_edge(clk) then
         instr <= rom(to_integer(pc_next));
         pc    <= pc_next;
         if (reset = '1') then
            running <= '0';
         elsif (running = '0') then
            running <= start;
         else
            if (writeA = '1') then A <= result; end if;
            if (writeA = '1' or (isALU = '1' and fn = "111")) then flagZ <= resZ; end if;
            if (setC = '1') then flagC <= sum(32) xor subtract; end if;    -- ADD: carry, SUB / CMP: borrow
            if (isMisc = '1' and mop = "0110") then running <= '0'; end if;   -- WAIT
         end if;
      end if;
   end process;

end architecture;
